/* Returns the level difference (target - current) clamped to +/-12, and sets *changedFlag if it is nonzero. */ s8 clampLevelStep(s32 currentLevel, s32 targetLevel, s8 *changedFlag) {
    s16 diff;
    s16 step;

    diff = (targetLevel & 0xFF) - (currentLevel & 0xFF);
    step = diff;
    if (diff >= 0xD) {
        step = 0xC;
    }
    if (step < -0xC) {
        step = -0xC;
    }
    if ((step << 0x10) != 0) {
        *changedFlag = 1;
    }
    return (s8) step;
}
